module robot_reach (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] char,\n    input wire char_valid,\n    input wire [6:0] len,\n    input wire signed [31:0] a,\n    input wire signed [31:0] b,\n    output reg result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] RECEIVE = 2'd1;\n    localparam [1:0] CHECK = 2'd2;\n    localparam [1:0] FINISHED = 2'd3;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [1:0] next_state;\n    reg [6:0] count;\n    reg signed [31:0] current_x;\n    reg signed [31:0] current_y;\n    reg signed [31:0] dx;\n    reg signed [31:0] dy;\n    reg [6:0] index;\n    reg signed [31:0] x_mem [0:100];\n    reg signed [31:0] y_mem [0:100];\n    integer i;  // For initialization loop\n\n    // Helper signals\n    wire signed [31:0] ax;\n    wire signed [31:0] by;\n    wire signed [63:0] prod1;\n    wire signed [63:0] prod2;\n    wire sign_ok_dx;\n    wire sign_ok_dy;\n\n    assign ax = a - x_mem[index];\n    assign by = b - y_mem[index];\n    assign prod1 = ax * dy;\n    assign prod2 = by * dx;\n    assign sign_ok_dx = (dx > 32'sd0 && ax >= 32'sd0) || (dx < 32'sd0 && ax <= 32'sd0) || (dx == 32'sd0);\n    assign sign_ok_dy = (dy > 32'sd0 && by >= 32'sd0) || (dy < 32'sd0 && by <= 32'sd0) || (dy == 32'sd0);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            count <= 7'd0;\n            current_x <= 32'sd0;\n            current_y <= 32'sd0;\n            dx <= 32'sd0;\n            dy <= 32'sd0;\n            index <= 7'd0;\n            for (i = 0; i <= 100; i = i + 1) begin\n                x_mem[i] <= 32'sd0;\n                y_mem[i] <= 32'sd0;\n            end\n        end else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        current_x <= 32'sd0;\n                        current_y <= 32'sd0;\n                        count <= 7'd0;\n                        x_mem[0] <= 32'sd0;\n                        y_mem[0] <= 32'sd0;\n                        next_state <= RECEIVE;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                RECEIVE: begin\n                    if (char_valid) begin\n                        case (char)\n                            8'h55, 8'h75: current_y <= current_y + 32'sd1;  // 'U'/'u'\n                            8'h44, 8'h64: current_y <= current_y - 32'sd1;  // 'D'/'d'\n                            8'h4C, 8'h6C: current_x <= current_x - 32'sd1;  // 'L'/'l'\n                            8'h52, 8'h72: current_x <= current_x + 32'sd1;  // 'R'/'r'\n                            default: ; // Ignore invalid\n                        endcase\n\n                        x_mem[count + 7'd1] <= current_x;\n                        y_mem[count + 7'd1] <= current_y;\n                        count <= count + 7'd1;\n\n                        if (count == len - 7'd1) begin\n                            dx <= current_x;\n                            dy <= current_y;\n                            index <= 7'd0;\n                            next_state <= CHECK;\n                        end else begin\n                            next_state <= RECEIVE;\n                        end\n                    end else begin\n                        next_state <= RECEIVE;\n                    end\n                end\n\n                CHECK: begin\n                    if (index <= len) begin\n                        if (dx == 32'sd0 && dy == 32'sd0) begin\n                            if (a == x_mem[index] && b == y_mem[index]) begin\n                                result <= 1'b1;\n                                next_state <= FINISHED;\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end else if (dx == 32'sd0) begin\n                            if (a == x_mem[index]) begin\n                                if (by == 32'sd0) begin\n                                    result <= 1'b1;\n                                    next_state <= FINISHED;\n                                end else if ((dy != 32'sd0) && (by % dy == 32'sd0)) begin\n                                    if (by / dy >= 32'sd0) begin\n                                        result <= 1'b1;\n                                        next_state <= FINISHED;\n                                    end else begin\n                                        index <= index + 7'd1;\n                                    end\n                                end else begin\n                                    index <= index + 7'd1;\n                                end\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end else if (dy == 32'sd0) begin\n                            if (b == y_mem[index]) begin\n                                if (ax == 32'sd0) begin\n                                    result <= 1'b1;\n                                    next_state <= FINISHED;\n                                end else if ((dx != 32'sd0) && (ax % dx == 32'sd0)) begin\n                                    if (ax / dx >= 32'sd0) begin\n                                        result <= 1'b1;\n                                        next_state <= FINISHED;\n                                    end else begin\n                                        index <= index + 7'd1;\n                                    end\n                                end else begin\n                                    index <= index + 7'd1;\n                                end\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end else begin\n                            if (prod1 == prod2 && sign_ok_dx && sign_ok_dy) begin\n                                result <= 1'b1;\n                                next_state <= FINISHED;\n                            end else begin\n                                index <= index + 7'd1;\n                            end\n                        end\n                    end else begin\n                        result <= 1'b0;\n                        next_state <= FINISHED;\n                    end\n                end\n\n                FINISHED: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule